def can_transform(a, b):
    if len(a) != len(b):
        return "NO"

    for i in range(len(a)):
        if a[i] == '1' and b[i] == '0':
            return "NO"

    return "YES"

# Read input
a = input().strip()
b = input().strip()

# Check if transformation is possible and print the result
print(can_transform(a, b))
